from z3 import *

n = 7

# Create integer variables
X = [[Int(f'x_{i}_{j}') for j in range(n)] for i in range(n)]

s = Solver()

# Domain: each cell is in {0, ..., n-1}
for i in range(n):
    for j in range(n):
        s.add(And(X[i][j] >= 0, X[i][j] <= n-1))

# Idempotent diagonal
for i in range(n):
    s.add(X[i][i] == i)

# Latin square: each row is a permutation
for i in range(n):
    s.add(Distinct([X[i][j] for j in range(n)]))

# Latin square: each column is a permutation
for j in range(n):
    s.add(Distinct([X[i][j] for i in range(n)]))

# QG3: x[x[i][j]][x[j][i]] = i
# Encode using a big disjunction for each (i,j)
for i in range(n):
    for j in range(n):
        a = X[i][j]
        b = X[j][i]
        # For each possible value p of a and q of b, we need:
        # (a == p and b == q) => X[p][q] == i
        # This is equivalent to: (a != p) OR (b != q) OR (X[p][q] == i)
        for p in range(n):
            for q in range(n):
                s.add(Or(a != p, b != q, X[p][q] == i))

print("Solving...")
result = s.check()
print(result)

if result == sat:
    m = s.model()
    grid = [[m.evaluate(X[i][j]).as_long() for j in range(n)] for i in range(n)]
    for row in grid:
        print(row)
    flat = [grid[i][j] for i in range(n) for j in range(n)]
    print("Flat:", flat)
else:
    print("UNSAT")

