import itertools
import sys

n = 7

# We'll use a backtracking approach
# The grid is filled cell by cell
# We maintain row and column sets to ensure Latin square property

# Let's think about the structure more carefully
# QG3: x[x[i][j]][x[j][i]] = i

# This means that for any i,j:
# Let a = x[i][j], b = x[j][i]
# Then x[a][b] = i and x[b][a] = j

# So the pairs (i,j) and (a,b) form a "cycle" of length 2 in some sense.
# x[i][j] = a, x[j][i] = b, x[a][b] = i, x[b][a] = j

# This is reminiscent of the property that the quasigroup is "symmetric" in some way.

# Let me try to use a SAT solver approach with pycosat

import pycosat

# We'll encode each cell as a set of boolean variables
# var(i,j,k) means x[i][j] = k
# We'll use a 1-indexed variable system

def var(i, j, k):
    return i * n * n + j * n + k + 1

clauses = []

# Each cell has at least one value
for i in range(n):
    for j in range(n):
        clauses.append([var(i, j, k) for k in range(n)])

# Each cell has at most one value (pairwise negative)
for i in range(n):
    for j in range(n):
        for k1 in range(n):
            for k2 in range(k1+1, n):
                clauses.append([-var(i, j, k1), -var(i, j, k2)])

# Each row has each value at least once (so exactly once, given the above)
for i in range(n):
    for k in range(n):
        clauses.append([var(i, j, k) for j in range(n)])

# Each column has each value at least once
for j in range(n):
    for k in range(n):
        clauses.append([var(i, j, k) for i in range(n)])

# Idempotent diagonal
for i in range(n):
    clauses.append([var(i, i, i)])

# QG3: x[x[i][j]][x[j][i]] = i
# For each i,j, and for each possible a,b:
# If x[i][j] = a and x[j][i] = b, then x[a][b] = i
# This is: (x[i][j] = a) AND (x[j][i] = b) => (x[a][b] = i)
# Which is: NOT(x[i][j] = a) OR NOT(x[j][i] = b) OR (x[a][b] = i)
# In CNF: [-var(i,j,a), -var(j,i,b), var(a,b,i)]

for i in range(n):
    for j in range(n):
        for a in range(n):
            for b in range(n):
                clauses.append([-var(i, j, a), -var(j, i, b), var(a, b, i)])

print(f"Number of clauses: {len(clauses)}")
print(f"Number of variables: {n*n*n}")

# Solve
print("Solving with pycosat...")
solution = pycosat.solve(clauses)
print(f"Result: {solution}")

if solution != "UNSAT" and solution is not None:
    # Extract the grid
    grid = [[0 for _ in range(n)] for _ in range(n)]
    for i in range(n):
        for j in range(n):
            for k in range(n):
                if solution[var(i,j,k)-1] > 0:
                    grid[i][j] = k
    for row in grid:
        print(row)
    flat = [grid[i][j] for i in range(n) for j in range(n)]
    print("Flat:", flat)
else:
    print("UNSATISFIABLE")
